styles:
/* A query container has no width of its own, so a layout that frames it with a flex row would shrink it to nothing: the width is stated. */
.b-demo-footer {
    container-type: inline-size;
    width: 100%;
    margin-top: 4rem;
    border-top: 1px solid var(--line, #e3e6ea);
    color: var(--muted, #5b6570);
    font-size: 0.875rem;
}

.b-demo-footer__inner {
    max-width: var(--page, 68rem);
    margin: 0 auto;
    padding: 2rem 1rem;
}

.b-demo-footer__columns {
    display: grid;
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.b-demo-footer__heading {
    display: block;
    margin-bottom: 0.5rem;
    color: var(--ink, #1f2328);
    font-weight: 600;
    text-decoration: none;
}

.b-demo-footer__list {
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-demo-footer__item + .b-demo-footer__item {
    margin-top: 0.25rem;
}

.b-demo-footer__link {
    color: inherit;
    text-decoration: none;
}

.b-demo-footer__link:hover {
    color: var(--accent, #1c64d8);
}

.b-demo-footer__copyright {
    margin: 0;
}

@container (min-width: 40rem) {
    .b-demo-footer__columns {
        grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
    }
}
